use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [proc_macro] pub fn import_cargo_lock (input : TokenStream) -> TokenStream { let path = parse_macro_input ! (input as LitStr) ; let cargo_lock_path = path . value () ; let lock_content = std :: fs :: read_to_string (& cargo_lock_path) . unwrap_or_else (| e | panic ! ("Failed to read Cargo.lock at {}: {}" , cargo_lock_path , e)) ; let lockfile = Lockfile :: from_str (& lock_content) . unwrap_or_else (| e | panic ! ("Failed to parse Cargo.lock: {}" , e)) ; let mut packages = Vec :: new () ; for package in lockfile . packages { if let Some (source) = & package . source { if source . is_path () { let name = package . name . as_str () ; let path_str = source . url () . path () ; packages . push (quote ! { CrateInfo { name : # name , path : # path_str } }) ; } } else { let name = package . name . as_str () ; packages . push (quote ! { CrateInfo { name : # name , path : # name } }) ; } } let expanded = quote ! { { # [derive (Debug , Clone)] pub struct CrateInfo { pub name : &'static str , pub path : &'static str , } const CARGO_LOCK_DATA : & [CrateInfo] = & [# (# packages) ,*] ; CARGO_LOCK_DATA } } ; TokenStream :: from (expanded) }